-- ONE-OFF, already applied 24/11/2026 (do not re-run): copies each customer's location into dr.sites and folds
-- same-owner customers into one customer with several sites. Empty customer shells were deleted afterwards.
begin;
insert into dr.sites(customer_id, label, area, address, lat, lng, map_url, deye_id, platform_name, notes)
select c.id, coalesce(nullif(c.area, ''), 'الموقع'), c.area, c.address, c.lat, c.lng, c.map_url,
  (regexp_match(c.notes, 'Deye #(\d+)'))[1]::bigint, c.platform_name,
  (regexp_match(c.notes, '(Deye #\d+ [^·]*kWp)'))[1]
from dr.customers c where not exists (select 1 from dr.sites s where s.customer_id = c.id);
update dr.customers set notes = regexp_replace(notes, ' · ربط Deye بحاجة تأكيد', '', 'g') where notes like '%بحاجة تأكيد%';
update dr.sites set notes = regexp_replace(notes, '^من ', '') where notes like 'من %';
update dr.sites set label = 'شوكين' where customer_id = (select id from dr.customers where name = 'الحاج علي امين');
update dr.sites set label = 'شوكين — Deye' where customer_id = (select id from dr.customers where name = 'علي امين (شوكين)');
update dr.sites set customer_id = (select id from dr.customers where name = 'الحاج علي امين') where customer_id = (select id from dr.customers where name = 'علي امين (شوكين)');
update dr.tasks set customer_id = (select id from dr.customers where name = 'الحاج علي امين') where customer_id = (select id from dr.customers where name = 'علي امين (شوكين)');
update dr.reports set customer_id = (select id from dr.customers where name = 'الحاج علي امين') where customer_id = (select id from dr.customers where name = 'علي امين (شوكين)');
update dr.expenses set customer_id = (select id from dr.customers where name = 'الحاج علي امين') where customer_id = (select id from dr.customers where name = 'علي امين (شوكين)');
update dr.plans set customer_id = (select id from dr.customers where name = 'الحاج علي امين') where customer_id = (select id from dr.customers where name = 'علي امين (شوكين)');
update dr.customers d set notes = concat_ws(' · ', d.notes, 'علي امين (شوكين)' || ': ' || s.notes) from dr.customers s where d.name = 'الحاج علي امين' and s.name = 'علي امين (شوكين)' and coalesce(s.notes,'') <> '';
delete from dr.customers where name = 'علي امين (شوكين)';
