update dr.tasks set customer_id = (select id from dr.customers where name = 'Ali Ezzeddine') where customer_id = (select id from dr.customers where name = 'Abo Ali ezzeddin New');
update dr.reports set customer_id = (select id from dr.customers where name = 'Ali Ezzeddine') where customer_id = (select id from dr.customers where name = 'Abo Ali ezzeddin New');
update dr.expenses set customer_id = (select id from dr.customers where name = 'Ali Ezzeddine') where customer_id = (select id from dr.customers where name = 'Abo Ali ezzeddin New');
update dr.plans set customer_id = (select id from dr.customers where name = 'Ali Ezzeddine') where customer_id = (select id from dr.customers where name = 'Abo Ali ezzeddin New');
update dr.customers d set notes = concat_ws(' · ', d.notes, 'Abo Ali ezzeddin New' || ': ' || s.notes) from dr.customers s where d.name = 'Ali Ezzeddine' and s.name = 'Abo Ali ezzeddin New' and coalesce(s.notes,'') <> '';
delete from dr.customers where name = 'Abo Ali ezzeddin New';
